use core.files as files
use core.process as process
use core.encoding.json as json
use core.text as text

#Codable
struct Report {
    count: DataTree
    name: String
    note: String
}

fn run() {
    path :: process.argv().get(1) ?? panic("missing path")
    input :: files.read(path) ?? panic("read failed")
    name := ""
    count := json.decode("0")
    note := ""
    loop row in input.lines() {
        fields :: text.splitn(row, "\t", 2)
        key :: fields.get(0) ?? panic("invalid report field")
        value :: fields.get(1) ?? panic("invalid report field")
        if key == "name" {
            name = value
        } else if key == "count" {
            count = json.decode(value)
        } else if key == "note" {
            note = value
        } else {
            panic("unknown report field")
        }
    }
    report :: Report{count: count, name: name, note: note}
    encoded :: json.to_string(report)
    print(encoded)
}
